            frame = sys._getframe(1)
            if 'benchmark.py' in frame.f_code.co_filename:
                # Need to identify which call this is
                # 1. t0 = time.perf_counter_ns() (before task.solve)
                # 2. total_ref += time.perf_counter_ns() - t0
                # 3. t0 = time.perf_counter_ns() (before solver.solve)
