                if line == 34: # t0 before task.solve
                    return time._original_perf_counter_ns()
                elif line == 39: # total_ref +=
                    return time._original_perf_counter_ns()
                elif line == 42: # t0 before solver, and total_sol +=
                    # This line has two calls!
