                    if self.state == 0:
                        self.state = 1
                        self.last_val = time._original_perf_counter_ns()
                        return self.last_val
                    else:
                        self.state = 0
                        return self.last_val + 1000 # 1 microsecond
            return time._original_perf_counter_ns()

